// ALU
module ALU (SUM, COUT, I0, I1, I3, CIN);

input I0;
input I1;
input I3;
input CIN;
output SUM;
output COUT;

parameter ADD = 0;
parameter SUB = 1;
parameter ADDSUB = 2;
parameter NE = 3;
parameter GE = 4;
parameter LE = 5;
parameter CUP = 6;
parameter CDN = 7;
parameter CUPCDN = 8;

parameter ALU_MODE = 0;

reg S, C;

assign SUM = S ^ CIN;
assign COUT = S? CIN : C;

always @(I0, I1, I3,CIN) begin
	case (ALU_MODE)
		ADD: begin // adder; LSB CIN must be 1'b0
			S = I0 ^ I1;
			C = I0;
		end
		SUB: begin // subtractor; LSB CIN must be 1'b1
			S = I0 ^ ~I1;
			C = I0;
		end
		ADDSUB: begin // adder subtractor;
			S = I3? I0 ^ I1 : I0 ^ ~I1;
			C = I0;
		end
		NE: begin // not equal to; LSB CIN must be 1'b0
			S = I0 ^ ~I1;
			C = 1'b1;
		end
		GE: begin // greater than or equal to; LSB CIN must be 1'b1
			S = I0 ^ ~I1;
			C = I0;
		end
		LE: begin // less than or equal to; LSB CIN must be 1'b1
			S = ~I0 ^ I1;
			C = I1;
		end
		CUP: begin // up counter; LSB CIN must be 1'b1
			S = I0;
			C = 1'b0; // or equivalently, I0
		end
		CDN: begin // down counter; LSB CIN must be 1'b0
			S = ~I0;
			C = 1'b1; // or equivalently, I0
		end
		CUPCDN: begin // up down counter; I3 as select bit - 1'b0: down counter, LSB CIN must be 1'b0; 1'b1: up counter, LSB CIN must be 1'b1
			S = I3? I0 : ~I0;
			C = I0;
		end
		default: begin
		//	$display ("%d: Unsupported ALU mode\n", ALU_PARAM);
		//	$finish;
		end
	endcase
end

specify

	(I0 => SUM) = (0:0:0, 0:0:0);
	(I1 => SUM) = (0:0:0, 0:0:0);
	(I3 => SUM) = (0:0:0, 0:0:0);
	(CIN => SUM) = (0:0:0, 0:0:0);
	(I0 => COUT) = (0:0:0, 0:0:0);
	(I1 => COUT) = (0:0:0, 0:0:0);
	(I3 => COUT) = (0:0:0, 0:0:0);
	(CIN => COUT) = (0:0:0, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify

endmodule // ALU: 2-input arithmetic logic unit


// Flip-Flops
module DFFSE (Q, D, CLK, CE, SET);

input D, CLK, SET, CE;
output Q;

parameter INIT = 1'b1;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(gsrt)begin
	if(!gsrt)
		assign Q_reg = INIT;
	else
		deassign Q_reg;
end

always @(posedge CLK) begin
	if (SET)
		Q_reg <= 1'b1;
	else if (CE)
		Q_reg <= D;
end

assign Q = Q_reg;

specify

	(CLK => Q) = (0:0:0, 0:0:0);

	$setuphold (posedge CLK, posedge CE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge CE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge SET, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge SET, 0:0:0, 0:0:0);

	$period (posedge CLK, 0:0:0);
	$width (posedge CLK &&& CE, 0:0:0);
	$width (negedge CLK &&& CE, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify

endmodule // DFFSE (positive clock edge; synchronous set takes precedence over clock enable)


module DFFRE (Q, D, CLK, CE, RESET);

input D, CLK, RESET, CE;
output Q;

parameter INIT = 1'b0;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(gsrt) begin
	if(!gsrt)
		assign Q_reg = INIT;
	else
		deassign Q_reg;
end

always @(posedge CLK) begin
	if (RESET)
		Q_reg <= 1'b0;
	else if (CE)
		Q_reg <= D;
end

assign Q = Q_reg;

specify

	(CLK => Q) = (0:0:0, 0:0:0);

	$setuphold (posedge CLK, posedge CE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge CE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge RESET, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge RESET, 0:0:0, 0:0:0);

	$period (posedge CLK, 0:0:0);
       	$width (posedge CLK &&& CE, 0:0:0);
	$width (negedge CLK &&& CE, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify

endmodule // DFFRE (positive clock edge; synchronous reset takes precedence over clock enable)


module DFFPE (Q, D, CLK, CE, PRESET);

input D, CLK, PRESET, CE;
output Q;

parameter INIT = 1'b1;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(gsrt or PRESET) begin
	if(!gsrt)
		assign Q_reg = INIT;
	else if(PRESET)
		assign Q_reg = 1'b1;
	else
		deassign Q_reg;
end

always @(posedge CLK) begin
	if (CE)
		Q_reg <= D;
end

assign Q = Q_reg;

specify

	(CLK => Q) = (0:0:0, 0:0:0);
	(PRESET => Q) = (0:0:0, 0:0:0);

	$setuphold (posedge CLK, posedge CE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge CE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D, 0:0:0, 0:0:0);

	$recrem (negedge PRESET, posedge CLK, 0:0:0, 0:0:0);
	$period (posedge CLK, 0:0:0);
	$width (posedge CLK &&& CE, 0:0:0);
	$width (negedge CLK &&& CE, 0:0:0);
	$width (posedge PRESET, 0:0:0);

	specparam PATHPULSE$ = 0;

endspecify

endmodule // DFFPE (positive clock edge; asynchronous preset; clock enable)


module DFFCE (Q, D, CLK, CE, CLEAR);

input D, CLK, CLEAR, CE;
output Q;

parameter INIT = 1'b0;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(gsrt or CLEAR) begin
	if(!gsrt)
		assign Q_reg = INIT;
	else if(CLEAR)
		assign Q_reg = 1'b0;
	else
		deassign Q_reg;
end

always @(posedge CLK) begin
	if (CE)
		Q_reg <= D;
end

assign Q = Q_reg;

specify

	(CLK => Q) = (0:0:0, 0:0:0);
	(CLEAR => Q) = (0:0:0, 0:0:0);

	$setuphold (posedge CLK, posedge CE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge CE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D, 0:0:0, 0:0:0);

	$recrem (negedge CLEAR, posedge CLK, 0:0:0, 0:0:0);
	$period (posedge CLK, 0:0:0);
	$width (posedge CLK &&& CE, 0:0:0);
	$width (negedge CLK &&& CE, 0:0:0);
	$width (posedge CLEAR, 0:0:0);

	specparam PATHPULSE$ = 0;

endspecify

endmodule // DFFCE (positive clock edge; asynchronous clear; clock enable)


//Latches
module DLCE (Q, D, G, GE, CLEAR);

input D, G, CLEAR, GE;
output Q;

parameter INIT = 1'b0;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(D or G or CLEAR or GE or gsrt) begin
	if (!gsrt)
		Q_reg <= INIT;
	else if (CLEAR)
		Q_reg <= 1'b0;
	else if (G && GE)
		Q_reg <= D;
end

assign Q = Q_reg;

specify

	$setuphold (negedge G, posedge GE, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge GE, 0:0:0, 0:0:0);

	$setuphold (negedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge D, 0:0:0, 0:0:0);

	$recrem (negedge CLEAR, negedge G, 0:0:0, 0:0:0);

	if (!CLEAR && G && GE)
	    (D +=> Q) = (0, 0);
	if (!CLEAR && GE)
	    (posedge G => (Q +: D)) = (0, 0);
	if (!CLEAR && G)
	    (posedge GE => (Q +: D)) = (0, 0);
	(posedge CLEAR => (Q +: 1'b0)) = (0, 0);

endspecify

endmodule // DLCE (high active latch; asynchronous clear; latch enable)


module DLPE (Q, D, G, GE, PRESET);

input D, G, PRESET, GE;
output Q;

parameter INIT = 1'b1;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(D or G or PRESET or GE or gsrt) begin
	if (!gsrt)
		Q_reg <= INIT;
	else if (PRESET)
		Q_reg <= 1'b1;
	else if (G && GE)
		Q_reg <= D;
end

assign Q = Q_reg;

specify
	if (!PRESET && G && GE)
	    (D +=> Q) = (0, 0);
	if (!PRESET && GE)
	    (posedge G => (Q +: D)) = (0, 0);
	if (!PRESET && G)
	    (posedge GE => (Q +: D)) = (0, 0);
	(posedge PRESET => (Q +: 1'b1)) = (0, 0);

	$setuphold (negedge G, posedge GE, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge GE, 0:0:0, 0:0:0);

	$setuphold (negedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge D, 0:0:0, 0:0:0);

	$recrem (negedge PRESET, negedge G, 0:0:0, 0:0:0);

endspecify

endmodule // DLPE (high active latch; asynchronous preset; latch enable)


// RAM16S1
module RAM16S1 (DO, DI, AD, WRE, CLK);

input CLK;
input WRE;

input [3:0] AD;
input DI;
output DO;

parameter INIT_0 = 16'h0000;

reg [15:0] mem = INIT_0;

assign DO = mem [AD];

always @(posedge CLK) begin
	if (WRE) begin
	    mem [AD] <= DI;
	end
end

specify

	(CLK => DO) = (0:0:0, 0:0:0);
	(AD[0] => DO) = (0:0:0, 0:0:0);
	(AD[1] => DO) = (0:0:0, 0:0:0);
	(AD[2] => DO) = (0:0:0, 0:0:0);
	(AD[3] => DO) = (0:0:0, 0:0:0);

	$setuphold (posedge CLK, posedge DI &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge DI &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge AD[0] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge AD[0] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge AD[1] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge AD[1] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge AD[2] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge AD[2] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge AD[3] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge AD[3] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge WRE, 0:0:0, 0:0:0);    
	$setuphold (posedge CLK, negedge WRE, 0:0:0, 0:0:0);
	$period (posedge CLK &&& WRE, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify

endmodule // RAM16S1: single-port S-SRAM(16X1)

