end

assign DO[0] = mem0[RAD];
assign DO[1] = mem1[RAD];
assign DO[2] = mem2[RAD];
assign DO[3] = mem3[RAD];

always @(posedge CLK) begin
	if (WRE) begin
		mem0[WAD] <= DI[0];
		mem1[WAD] <= DI[1];
		mem2[WAD] <= DI[2];
		mem3[WAD] <= DI[3];
	end
end

specify

	(CLK => DO[0]) = (0:0:0, 0:0:0);
	(RAD[0] => DO[0]) = (0:0:0, 0:0:0);
	(RAD[1] => DO[0]) = (0:0:0, 0:0:0);
	(RAD[2] => DO[0]) = (0:0:0, 0:0:0);
	(RAD[3] => DO[0]) = (0:0:0, 0:0:0);
	(CLK => DO[1]) = (0:0:0, 0:0:0);
	(RAD[0] => DO[1]) = (0:0:0, 0:0:0);
	(RAD[1] => DO[1]) = (0:0:0, 0:0:0);
	(RAD[2] => DO[1]) = (0:0:0, 0:0:0);
	(RAD[3] => DO[1]) = (0:0:0, 0:0:0);
	(CLK => DO[2]) = (0:0:0, 0:0:0);
	(RAD[0] => DO[2]) = (0:0:0, 0:0:0);
	(RAD[1] => DO[2]) = (0:0:0, 0:0:0);
	(RAD[2] => DO[2]) = (0:0:0, 0:0:0);
	(RAD[3] => DO[2]) = (0:0:0, 0:0:0);
	(CLK => DO[3]) = (0:0:0, 0:0:0);
	(RAD[0] => DO[3]) = (0:0:0, 0:0:0);
	(RAD[1] => DO[3]) = (0:0:0, 0:0:0);
	(RAD[2] => DO[3]) = (0:0:0, 0:0:0);
	(RAD[3] => DO[3]) = (0:0:0, 0:0:0);

	$setuphold (posedge CLK, posedge DI[0] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge DI[0] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge DI[1] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge DI[1] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge DI[2] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge DI[2] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge DI[3] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge DI[3] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge WAD[0] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge WAD[0] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge WAD[1] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge WAD[1] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge WAD[2] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge WAD[2] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge WAD[3] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge WAD[3] &&& WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge WRE, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge WRE, 0:0:0, 0:0:0);

	$period (posedge CLK &&& WRE, 0:0:0);

	specparam PATHPULSE$ = 0;

endspecify

endmodule // RAM16SDP4: Semi dual-port S-SRAM(16X4)

