//TRUE LVDS 
module TLVDS_IBUF (O, I, IB);
output O;
input  I, IB;
reg O_oreg;
assign O = O_oreg;
always @(I or IB) begin
	if (I == 1'b1 && IB == 1'b0)
		O_oreg <= I;
	else if (I == 1'b0 && IB == 1'b1)
		O_oreg <= I;
    else if (I == 1'bx || IB == 1'bx)
		O_oreg <= 1'bx;
end

specify

	(I => O) = (0:0:0, 0:0:0);
	(IB => O) = (0:0:0, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify

endmodule

