//MIPI_IBUF
//BUF for mipi input
module MIPI_IBUF (OH, OL, OB, IO, IOB, I, IB, OEN, OENB, HSEN, HSREN);
output OH, OL, OB;
inout IO, IOB;
input  I, IB;
input OEN, OENB;
input HSEN, HSREN;
reg OH;

//LP mode
bufif0 IL_INST (IO,I,OEN);
bufif0 IB_INST (IOB,IB,OENB);

assign OL = IO;
assign OB = IOB;

//HS mode
always @(IO or IOB or HSEN)
begin
    if(HSEN)
    begin
        if (IO == 1'b1 && IOB == 1'b0)
        begin
		    OH <= IO;
        end else if (IO == 1'b0 && IOB == 1'b1) 
        begin
		    OH <= IO;
        end else if (IO == 1'bx || IOB == 1'bx) 
        begin
		    OH <= 1'bx;
        end
    end
end

specify

	(I => OL) = (0:0:0, 0:0:0);
        (I => IO) = (0:0:0, 0:0:0);
        (IO => OL) = (0:0:0, 0:0:0);
        (IO => OH) = (0:0:0, 0:0:0);
        (IB => OB) = (0:0:0, 0:0:0);
        (IB => IOB) = (0:0:0, 0:0:0);
        (IOB => OB) = (0:0:0, 0:0:0);
        (OEN => OL) = (0:0:0, 0:0:0);
        (OEN => IO) = (0:0:0, 0:0:0);
        (OENB => OB) = (0:0:0, 0:0:0);
        (OENB => IOB) = (0:0:0, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify

endmodule

//OBUF for mipi output, gw5a-25
module MIPI_OBUF_A (O, OB, IO, IOB, I, IB, IL, OEN, OENB, MODESEL);
output O, OB;
input  I, IB, IL, MODESEL;
inout IO, IOB;
input OEN, OENB;

//LP mode
bufif0 IL_INST (IO, IL, (OEN || MODESEL));
bufif0 IB_INST (IOB, IB, (OENB || MODESEL));

bufif0  (O, IO, MODESEL); //LP RX 
bufif0  (OB, IOB, MODESEL);

//HS mode
bufif1 I_HS (I_hs, I, MODESEL);

bufif0  (IO, I_hs, (OEN || (!MODESEL)));
notif0  (IOB, I_hs, (OENB || (!MODESEL)));

specify

	(I => IO) = (0:0:0, 0:0:0);
        (I => IOB) = (0:0:0, 0:0:0);
        (I => O) = (0:0:0, 0:0:0);
        (I => OB) = (0:0:0, 0:0:0);
        (OEN => IO) = (0:0:0, 0:0:0);
        (OEN => IOB) = (0:0:0, 0:0:0);
        (IO => O) = (0:0:0, 0:0:0);
        (IO => OB) = (0:0:0, 0:0:0);
        (IB => IO) = (0:0:0, 0:0:0);
        (IB => IOB) = (0:0:0, 0:0:0);
        (IB => OB) = (0:0:0, 0:0:0);
        (IOB => O) = (0:0:0, 0:0:0);
        (IOB => OB) = (0:0:0, 0:0:0);
        (MODESEL => O) = (0:0:0, 0:0:0);
        (MODESEL => OB) = (0:0:0, 0:0:0);
        (OENB => IO) = (0:0:0, 0:0:0);
        (OENB => IOB) = (0:0:0, 0:0:0);
        (OENB => OB) = (0:0:0, 0:0:0);
        (IL => O) = (0:0:0, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify

endmodule



