//IOBUF for I3C mode
module I3C_IOBUF (O, IO, I, MODESEL);
output O;
inout IO;
input  I, MODESEL;
reg oreg;

buf OB (O, IO);

always @(I or MODESEL) begin
    if(MODESEL == 1'b1) begin //open-drain mode
        if(I == 1'b0) begin //pull down
            oreg <= 1'b0;
        end else begin //floating
            oreg <= 1'bz;
        end
    end else begin //normal mode
        oreg <= I;
    end
end

assign IO = oreg;

specify

	(I => IO) = (0:0:0, 0:0:0);
	(I => O) = (0:0:0, 0:0:0);
	(MODESEL => IO) = (0:0:0, 0:0:0);
	(MODESEL => O) = (0:0:0, 0:0:0);
	(IO => O) = (0:0:0, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify

endmodule

