        $setuphold (posedge CLKA, posedge DI[19], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, negedge DI[19], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, posedge DI[20], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, negedge DI[20], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, posedge DI[21], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, negedge DI[21], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, posedge DI[22], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, negedge DI[22], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, posedge DI[23], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, negedge DI[23], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, posedge DI[24], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, negedge DI[24], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, posedge DI[25], 0:0:0, 0:0:0);
