specify

        (ADDSUB[1] => DOUT[0]) = (0:0:0, 0:0:0);
        (CASISEL => DOUT[0]) = (0:0:0, 0:0:0);
	(ACCSEL => DOUT[0]) = (0:0:0, 0:0:0);
