        $setuphold (negedge FCLK, negedge D, 0:0:0, 0:0:0);
        $setuphold (posedge FCLK, posedge CALIB, 0:0:0, 0:0:0);
        $setuphold (posedge FCLK, negedge CALIB, 0:0:0, 0:0:0);
        $recrem (negedge RESET, negedge FCLK, 0:0:0, 0:0:0);
        $recrem (negedge RESET, posedge FCLK, 0:0:0, 0:0:0);
        $recrem (negedge RESET, posedge PCLK, 0:0:0, 0:0:0);

	$period (posedge PCLK, 0:0:0);
	$period (posedge FCLK, 0:0:0);
	$period (negedge FCLK, 0:0:0);
	specparam PATHPULSE$ = 0;
	
endspecify

endmodule // IDES16 (16 to 1 deserializer)

//IDES4_MEM
module IDES4_MEM (Q0, Q1, Q2, Q3, D, WADDR, RADDR, CALIB, PCLK, FCLK, ICLK, RESET);

input PCLK, D, ICLK, FCLK, RESET, CALIB;
input [2:0] WADDR;
input [2:0] RADDR;
output Q0,Q1,Q2,Q3;
wire grstn,lrstn;
reg d0_reg;
reg [3:0] D_data;
reg [3:0] Q_data;
reg [3:0] data;
reg data_en1,data_en;
reg data_sel,calib_state;
reg reset_delay;
wire calib_rising_p;
reg calib_0,calib_1,calib_2;
wire dcnt_en;
reg d0_reg1,d0_reg2,d0_reg3,d0_reg4,d1_reg1,d1_reg2,d1_reg3,d1_reg4;
reg [7:0] d0_mem;
reg [7:0] d1_mem;

initial begin
    calib_state = 1'b0;
    data_en1 = 1'b0;
    data_en = 1'b0;
    data_sel = 1'b0;
end

assign grstn = GSR.GSRO;
assign lrstn = (~RESET);

always @(posedge ICLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        d0_reg <= 0;
    end else if (!lrstn) begin
        d0_reg <= 0;
    end else begin
        d0_reg <= D;
    end
end

always @(negedge ICLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        d0_mem <= 0;
    end else if (!lrstn) begin
        d0_mem <= 0;
    end else begin
        d0_mem[WADDR] <= d0_reg;
    end
end

always @(negedge ICLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        d1_mem <= 0;
    end else if (!lrstn) begin
        d1_mem <= 0;
    end else begin
        d1_mem[WADDR] <= D;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        d0_reg1 <= 1'b0;
		d0_reg2 <= 1'b0;
		d0_reg3 <= 1'b0;
		d0_reg4 <= 1'b0;
        d1_reg1 <= 1'b0;
		d1_reg2 <= 1'b0;
		d1_reg3 <= 1'b0;
		d1_reg4 <= 1'b0;
    end else if (!lrstn) begin
        d0_reg1 <= 1'b0;
		d0_reg2 <= 1'b0;
		d0_reg3 <= 1'b0;
		d0_reg4 <= 1'b0;
        d1_reg1 <= 1'b0;
		d1_reg2 <= 1'b0;
		d1_reg3 <= 1'b0;
		d1_reg4 <= 1'b0;
    end else begin
        d0_reg1 <= d0_mem[RADDR];
		d0_reg2 <= d0_reg1;
		d0_reg3 <= d0_reg2;
		d0_reg4 <= d0_reg3;
        d1_reg1 <= d1_mem[RADDR];
		d1_reg2 <= d1_reg1;
		d1_reg3 <= d1_reg2;
		d1_reg4 <= d1_reg3;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        reset_delay <= 0;
    end else if (!lrstn) begin
        reset_delay <= 0;
    end else begin
        reset_delay <= 1;
    end
end

always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        calib_0 <= 0;
        calib_1 <= 0;
        calib_2 <= 0;
    end else begin
        calib_0 <= CALIB;
        calib_1 <= calib_0;
        calib_2 <= calib_1;
    end
end



assign calib_rising_p =  calib_1 & (~calib_2);
assign dcnt_en = ~(calib_rising_p & calib_state);

always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        calib_state <= 0;
        data_en1 <= 0;
        data_en  <= 0;
        data_sel <= 0;
    end else begin
        data_en <= ~data_en1;
        if (calib_rising_p) begin
            calib_state <= ~calib_state;
            data_sel <= ~data_sel;
        end else begin
            calib_state <= calib_state;
            data_sel <= data_sel;
        end
        
        if (dcnt_en) begin
            data_en1 <= ~data_en1;
        end else begin
            data_en1 <= data_en1;
        end
    end
end


always @(data_sel or d0_mem[RADDR] or d1_mem[RADDR]or d0_reg1 or d0_reg2 or d0_reg3 or d0_reg4 or d1_reg1 or d1_reg2 or d1_reg3 or d1_reg4) begin
    if(data_sel) begin
        D_data[3] = d0_reg2;
        D_data[2] = d1_reg3;
        D_data[1] = d0_reg3;
        D_data[0] = d1_reg4;
    end else begin
        D_data[3] = d1_reg3;
        D_data[2] = d0_reg3;
        D_data[1] = d1_reg4;
        D_data[0] = d0_reg4;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        data <= 0;
    end else if (!lrstn) begin
        data <= 0;
    end else if (data_en) begin
        data <= D_data;
    end
end

always @(posedge PCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        Q_data <= 0;
    end else if (!lrstn) begin
        Q_data <= 0;
    end else begin
        Q_data <= data;
    end
end

assign {Q3,Q2,Q1,Q0} = Q_data;

specify

	if(PCLK) (PCLK => Q0) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q1) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q2) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q3) = (0:0:0, 0:0:0);

	(RESET => Q0) = (0:0:0, 0:0:0);
	(RESET => Q1) = (0:0:0, 0:0:0);
	(RESET => Q2) = (0:0:0, 0:0:0);
	(RESET => Q3) = (0:0:0, 0:0:0);
	
	$setuphold (posedge ICLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge ICLK, negedge D, 0:0:0, 0:0:0);    
	$setuphold (negedge ICLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge D, 0:0:0, 0:0:0); 
	
	$setuphold (negedge ICLK, posedge WADDR[0], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge WADDR[0], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, posedge WADDR[1], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge WADDR[1], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, posedge WADDR[2], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge WADDR[2], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, posedge RADDR[0], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge RADDR[0], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, posedge RADDR[1], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge RADDR[1], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, posedge RADDR[2], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge RADDR[2], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, posedge CALIB, 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge CALIB, 0:0:0, 0:0:0);
	
    $recrem (negedge RESET, posedge PCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, posedge FCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, posedge ICLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, negedge ICLK, 0:0:0, 0:0:0);
		
	$period (posedge PCLK, 0:0:0);
	$period (posedge FCLK, 0:0:0);
	$period (posedge ICLK, 0:0:0);
	$period (negedge ICLK, 0:0:0);

	specparam PATHPULSE$ = 0;
	
    endspecify

endmodule //IDES4_MEM (4 to 1 deserializer with memory)

//IVIDEO
module IVIDEO (Q0, Q1, Q2, Q3, Q4, Q5, Q6, D, CALIB, PCLK, FCLK, RESET);

input D, FCLK, PCLK, CALIB, RESET;
output Q0, Q1, Q2, Q3, Q4, Q5, Q6;
wire grstn;
wire lrstn; 
assign grstn = GSR.GSRO;
assign lrstn = (~RESET);

reg d0_reg;
reg d1_reg;
reg [6:0] D_data;
reg [6:0] data;
reg [6:0] Q_data;
reg data_sel;
reg reset_delay;
wire calib_rising_p;
reg [2:0] calib_data;
wire dcnt_en,dsel_en;
reg d0_reg0,d0_reg1,d0_reg2,d1_reg0,d1_reg1,d1_reg2,d1_reg3;
reg d0_ireg,d0_ireg0,d1_ireg,d1_ireg1;
reg data_en0,data_en1;
wire data_en;
reg d_up;
wire cnt_rst;
wire data_en0_data,data_en1_data;
always @(negedge FCLK or negedge grstn or negedge lrstn)
begin
    if (!grstn)begin
		d0_ireg <= 0;
    end
    else if (!lrstn)begin
        d0_ireg <= 0;
    end
    else begin
		d0_ireg <= D;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn)
begin
    if (!grstn)begin
		d1_ireg <= 0;
    end
    else if (!lrstn)begin
		d1_ireg <= 0;
    end
    else begin
        d1_ireg <= D;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        reset_delay <= 1'b0;
    end else if (!lrstn) begin
        reset_delay <= 1'b0;
    end else begin
        reset_delay <= 1'b1;
    end
end

always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        calib_data <= 3'b0;
    end else begin
        calib_data <= {calib_data[1:0], CALIB};
    end
end

assign calib_rising_p =  ~(calib_data[1] && (~calib_data[2]));
assign dcnt_en =  calib_rising_p;
assign dsel_en = ~(~(data_sel & (data_en1 & (~data_en0)) & calib_rising_p) & (~((data_en0 & data_en1) & (~data_sel)))); 
assign cnt_rst = (~data_en0) & data_en1 & data_sel;

assign data_en0_data = ~(data_en0|cnt_rst);
assign data_en1_data = ~((~(data_en0 ^ data_en1))|cnt_rst);

always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        data_en1 <= 1'b0;
        data_en0 <= 1'b0;
    end else begin
        if(dcnt_en) begin
            data_en0 <= data_en0_data;
            data_en1 <= data_en1_data;
        end else begin
            data_en0 <= data_en0;
            data_en1 <= data_en1;
        end

    end
end
//
assign data_en = ~(~((data_en0 & (~data_en1)) & (~data_sel))&(~(((~data_en0) & (~data_en1)) & data_sel)));
always @(posedge FCLK or negedge reset_delay) begin
    if(!reset_delay) begin
        d_up <= 0;
    end else if(data_en) begin
        d_up <= 1;
    end else begin
        d_up <= 0;
    end
end

always @(posedge FCLK or negedge reset_delay) begin
    if(!reset_delay) begin
	    data_sel <=0; 
    end else begin
        if(dsel_en) begin
            data_sel <= ~data_sel;
        end else begin
            data_sel <= data_sel;
        end
    end
end
always @(posedge FCLK or negedge grstn  or negedge lrstn) begin
    if (!grstn) begin
        d0_ireg0 <= 1'b0;
        d0_reg <= 1'b0;
        d0_reg0 <= 1'b0;
        d0_reg1 <= 1'b0;
        d0_reg2 <= 1'b0;
        d1_ireg1 <= 1'b0;
        d1_reg <= 1'b0;
        d1_reg0 <= 1'b0;
        d1_reg1 <= 1'b0;
        d1_reg2 <= 1'b0;
        d1_reg3 <= 1'b0;
    end else if(!lrstn) begin
        d0_ireg0 <= 1'b0;
        d0_reg <= 1'b0;
        d0_reg0 <= 1'b0;
        d0_reg1 <= 1'b0;
        d0_reg2 <= 1'b0;
        d1_ireg1 <= 1'b0;
        d1_reg <= 1'b0;
        d1_reg0 <= 1'b0;
        d1_reg1 <= 1'b0;
        d1_reg2 <= 1'b0;
        d1_reg3 <= 1'b0;
    end else begin
		d0_ireg0 <= d0_ireg;
		d0_reg <= d0_ireg0;
        d0_reg0 <= d0_reg;
        d0_reg1 <= d0_reg0;
        d0_reg2 <= d0_reg1;
		d1_ireg1 <= d1_ireg;
		d1_reg <= d1_ireg1;
        d1_reg0 <= d1_reg;
        d1_reg1 <= d1_reg0;
        d1_reg2 <= d1_reg1;
        d1_reg3 <= d1_reg2;
    end
end

always @(data_sel or d0_reg or d0_reg0 or d0_reg1 or d0_reg2 or d1_reg0 or d1_reg1 or d1_reg2 or d1_reg3) begin
    if(data_sel) begin
        D_data[6] <= d0_reg;
        D_data[5] <= d1_reg;
        D_data[4] <= d0_reg0;
        D_data[3] <= d1_reg0;
        D_data[2] <= d0_reg1;
        D_data[1] <= d1_reg1;
        D_data[0] <= d0_reg2;
    end else begin
        D_data[6] <= d1_reg;
        D_data[5] <= d0_reg0;
        D_data[4] <= d1_reg0;
        D_data[3] <= d0_reg1;
        D_data[2] <= d1_reg1;
        D_data[1] <= d0_reg2;
        D_data[0] <= d1_reg2;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn)
begin
    if (!grstn)begin
        data <= 0;
    end
    else if (!lrstn)begin
        data <= 0;
    end
    else if (d_up)begin
        data <= D_data;
    end
end

always @(posedge PCLK or negedge grstn or negedge lrstn)
begin
    if (!grstn)begin
        Q_data <= 0;
    end
    else if (!lrstn)begin
        Q_data <= 0;
    end
    else begin
        Q_data <= data;
    end
end

assign {Q6, Q5, Q4, Q3, Q2, Q1, Q0} = Q_data;

specify

	if(PCLK) (PCLK => Q0) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q1) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q2) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q3) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q4) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q5) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q6) = (0:0:0, 0:0:0);

	(RESET => Q0) = (0:0:0, 0:0:0);
	(RESET => Q1) = (0:0:0, 0:0:0);
	(RESET => Q2) = (0:0:0, 0:0:0);
	(RESET => Q3) = (0:0:0, 0:0:0);
	(RESET => Q4) = (0:0:0, 0:0:0);
	(RESET => Q5) = (0:0:0, 0:0:0);
	(RESET => Q6) = (0:0:0, 0:0:0);
	
	$setuphold (posedge FCLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge D, 0:0:0, 0:0:0);   
	$setuphold (negedge FCLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge FCLK, negedge D, 0:0:0, 0:0:0);  
	
	$setuphold (posedge FCLK, posedge CALIB, 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge CALIB, 0:0:0, 0:0:0);
	
    $recrem (negedge RESET, posedge PCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, posedge FCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, negedge FCLK, 0:0:0, 0:0:0);
		
	$period (posedge PCLK, 0:0:0);
	$period (posedge FCLK, 0:0:0);
	$period (negedge FCLK, 0:0:0);

	specparam PATHPULSE$ = 0;
	
    endspecify

endmodule //IVIDEO (7 to 1 deserializer)


//IDES8_MEM
module IDES8_MEM (Q0, Q1, Q2, Q3, Q4, Q5, Q6, Q7, D, WADDR, RADDR, CALIB, PCLK, FCLK, ICLK, RESET);

input PCLK, D, ICLK, FCLK, RESET, CALIB;
input [2:0] WADDR;
input [2:0] RADDR;
output Q0,Q1,Q2,Q3,Q4,Q5,Q6,Q7;
wire grstn,lrstn;
reg d0_reg;
reg [7:0] D_data;
reg [7:0] Q_data;
reg [7:0] data;
reg data_en0,data_en1,data_en;
reg data_sel,calib_state;
reg reset_delay;
wire calib_rising_p;
reg calib_0,calib_1,calib_2;
wire dcnt_en;
reg d0_reg1,d0_reg2,d0_reg3,d0_reg4,d1_reg1,d1_reg2,d1_reg3,d1_reg4;
reg [7:0] d0_mem;
reg [7:0] d1_mem;

initial begin
    calib_state = 1'b0;
    data_en0 = 1'b0;
    data_en1 = 1'b0;
    data_en = 1'b0;
    data_sel = 1'b0;
end

assign grstn = GSR.GSRO;
assign lrstn = (~RESET);

always @(posedge ICLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        d0_reg <= 0;
    end else if (!lrstn) begin
        d0_reg <= 0;
    end else begin
        d0_reg <= D;
    end
end

always @(negedge ICLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        d0_mem <= 0;
    end else if (!lrstn) begin
        d0_mem <= 0;
    end else begin
        d0_mem[WADDR] <= d0_reg;
    end
end

always @(negedge ICLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        d1_mem <= 0;
    end else if (!lrstn) begin
        d1_mem <= 0;
    end else begin
        d1_mem[WADDR] <= D;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        d0_reg1 <= 1'b0;
        d0_reg2 <= 1'b0;
        d0_reg3 <= 1'b0;
	    d0_reg4 <= 1'b0;
        d1_reg1 <= 1'b0;
        d1_reg2 <= 1'b0;
        d1_reg3 <= 1'b0;
	    d1_reg4 <= 1'b0;
    end else if (!lrstn) begin
        d0_reg1 <= 1'b0;
        d0_reg2 <= 1'b0;
        d0_reg3 <= 1'b0;
	    d0_reg4 <= 1'b0;
        d1_reg1 <= 1'b0;
        d1_reg2 <= 1'b0;
        d1_reg3 <= 1'b0;
	    d1_reg4 <= 1'b0;
    end else begin
        d0_reg1 <= d0_mem[RADDR];
        d0_reg2 <= d0_reg1;
        d0_reg3 <= d0_reg2;
	    d0_reg4 <= d0_reg3;
        d1_reg1 <= d1_mem[RADDR];
        d1_reg2 <= d1_reg1;
        d1_reg3 <= d1_reg2;
	    d1_reg4 <= d1_reg3;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        reset_delay <= 0;
    end else if (!lrstn) begin
        reset_delay <= 0;
    end else begin
        reset_delay <= 1;
    end
end

always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        calib_0 <= 0;
        calib_1 <= 0;
        calib_2 <= 0;
    end else begin
        calib_0 <= CALIB;
        calib_1 <= calib_0;
        calib_2 <= calib_1;
    end
end


assign calib_rising_p =  calib_1 & (~calib_2);
assign dcnt_en = ~(calib_rising_p & calib_state);


always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        calib_state <= 0;
        data_en0 <= 0;
        data_en1 <= 0;
        data_en  <= 0;
        data_sel <= 0;
    end else begin
        data_en <= ~data_en1 & data_en0;
        if (calib_rising_p) begin
            calib_state <= ~calib_state;
            data_sel <= ~data_sel;
        end else begin
            calib_state <= calib_state;
            data_sel <= data_sel;
        end
        
        if (dcnt_en) begin
            data_en0 <= ~data_en0;
        end else begin
            data_en0 <= data_en0;
        end

        if (dcnt_en) begin
            data_en1 <= data_en0 ^ data_en1;
        end else begin
            data_en1 <= data_en1;
        end
    end
end

always @(data_sel or d0_mem[RADDR] or d1_mem[RADDR]or d0_reg1 or d0_reg2 or d0_reg3 or d0_reg4 or d1_reg1 or d1_reg2 or d1_reg3 or d1_reg4) begin
    if(data_sel) begin
        D_data[7] <= d0_mem[RADDR];
        D_data[6] <= d1_reg1;
        D_data[5] <= d0_reg1;
        D_data[4] <= d1_reg2;
        D_data[3] <= d0_reg2;
        D_data[2] <= d1_reg3;
        D_data[1] <= d0_reg3;
        D_data[0] <= d1_reg4;
    end else begin
        D_data[7] <= d1_reg1;
        D_data[6] <= d0_reg1;
        D_data[5] <= d1_reg2;
