        $setuphold (posedge PCLK, negedge D1, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D2, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D2, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D3, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D3, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D4, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D4, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D5, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D5, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D6, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D6, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D7, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D7, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D8, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D8, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D9, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D9, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D10, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D10, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D11, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D11, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D12, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D12, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D13, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D13, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D14, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D14, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, posedge D15, 0:0:0, 0:0:0);
        $setuphold (posedge PCLK, negedge D15, 0:0:0, 0:0:0);

        $recrem (negedge RESET, posedge PCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, negedge FCLK, 0:0:0, 0:0:0);
        $recrem (negedge RESET, posedge FCLK, 0:0:0, 0:0:0);

	$period (posedge PCLK, 0:0:0);
	$period (posedge FCLK, 0:0:0);
    
	$period (negedge PCLK, 0:0:0);
	$period (negedge FCLK, 0:0:0);


	specparam PATHPULSE$ = 0;
endspecify

endmodule

//IO delay
module IODELAY (DO, DF, DI, DLYSTEP, SDTAP, VALUE);

parameter C_STATIC_DLY = 0; //integer,0~255
parameter DYN_DLY_EN = "FALSE";//"TRUE","FALSE"
parameter ADAPT_EN = "FALSE";//"TRUE","FALSE"

input  DI;
input  SDTAP;
input  VALUE;
input  [7:0] DLYSTEP;
output DF;
output DO;

reg [7:0] delay_data,delay_data_adapt;
reg pre_value;
reg delay_out;
wire [7:0] delay_code;
wire [7:0] delay_data_real;
integer cnt_step,cnt_value;
reg cnt_start,cnt_step_start,cnt_value_start;

initial begin
    cnt_step = 0;
    cnt_value = 0;
    cnt_start = 1'b0;
    cnt_step_start = 1'b0;
    cnt_value_start = 1'b0;

end

assign delay_code = (DYN_DLY_EN == "FALSE")? C_STATIC_DLY : DLYSTEP;

always @(SDTAP or VALUE) begin
    if (!SDTAP) begin
        delay_data <= delay_code;
    end
end

always @(SDTAP or VALUE) begin
    if (SDTAP) begin
        if(pre_value == 1'b0 && VALUE == 1'b1) begin
            cnt_start <= 1'b1;
        end else begin
            cnt_start <= 1'b0;            
        end
    end
end
 
always @(negedge DI) begin
    if(cnt_start) begin
        if(cnt_value == 22) begin
            cnt_value <= 0;
            cnt_value_start <= 1'b1;
        end else  if(cnt_value == 15) begin
            cnt_step_start <= 1'b1;            
            cnt_value <= cnt_value + 1;
        end else begin
            cnt_value <= cnt_value + 1;
        end

        if(cnt_value_start == 1'b1) begin
            cnt_value <= 0;
        end
    end else begin
        cnt_value <= 0;
        cnt_value_start <= 1'b0;
        cnt_step_start <= 1'b0;            
    end
end

always @(negedge DI) begin
    if(cnt_step_start) begin
        if(cnt_step == 7) begin
            cnt_step <= 0;
        end else begin
            cnt_step <= cnt_step + 1;
        end
    end else begin
        cnt_step <= 0;    
    end
end


always @(SDTAP or VALUE or cnt_step or DLYSTEP or cnt_value_start) begin
    if (!SDTAP) begin
        delay_data_adapt <= DLYSTEP;
    end else begin
        if(cnt_value_start == 1'b1) begin
   	        if (delay_data_adapt < DLYSTEP)
            begin
                if(delay_data_adapt != DLYSTEP) begin
                    if (cnt_step == 7) begin
      		            delay_data_adapt <= delay_data_adapt + 1;
                    end
                end
            end else if (delay_data_adapt > DLYSTEP) begin
                if(delay_data_adapt != DLYSTEP) begin
                    if (cnt_step == 7) begin
      		            delay_data_adapt <= delay_data_adapt - 1;
                    end
                end
            end
  	    end
    end
end

always @(VALUE) begin;
    pre_value <= VALUE;
end

assign DF = ((C_STATIC_DLY > DLYSTEP) && (delay_data_adapt == DLYSTEP)) || ((C_STATIC_DLY < DLYSTEP) && (delay_data_adapt == DLYSTEP));

assign delay_data_real = (ADAPT_EN == "FALSE")? delay_data : delay_data_adapt;

//assign #(0.0125*(delay_data_real+1)) delay_out = DI;
always @(DI)
begin
    delay_out <= #(0.0125*(delay_data_real+1)) DI;
end

assign DO = delay_out;
specify
	(DI => DO) = (0:0:0, 0:0:0);
    (VALUE => DF) = (0:0:0, 0:0:0);
	(DLYSTEP[0] => DO) = (0:0:0, 0:0:0);
	(DLYSTEP[0] => DF) = (0:0:0, 0:0:0);
	(DLYSTEP[1] => DO) = (0:0:0, 0:0:0);
	(DLYSTEP[1] => DF) = (0:0:0, 0:0:0);
	(DLYSTEP[2] => DO) = (0:0:0, 0:0:0);
	(DLYSTEP[2] => DF) = (0:0:0, 0:0:0);
	(DLYSTEP[3] => DO) = (0:0:0, 0:0:0);
	(DLYSTEP[3] => DF) = (0:0:0, 0:0:0);
	(DLYSTEP[4] => DO) = (0:0:0, 0:0:0);
	(DLYSTEP[4] => DF) = (0:0:0, 0:0:0);
	(DLYSTEP[5] => DO) = (0:0:0, 0:0:0);
	(DLYSTEP[5] => DF) = (0:0:0, 0:0:0);
	(DLYSTEP[6] => DO) = (0:0:0, 0:0:0);
	(DLYSTEP[6] => DF) = (0:0:0, 0:0:0);
	(DLYSTEP[7] => DO) = (0:0:0, 0:0:0);
	(DLYSTEP[7] => DF) = (0:0:0, 0:0:0);
	specparam PATHPULSE$ = 0;
endspecify
endmodule // IODELAY (i/o delay in IOB)


module OSIDES32(Q, DF0, DF1, D, PCLK, FCLKP, FCLKN, FCLKQP, FCLKQN, RESET, SDTAP0, VALUE0, DLYSTEP0, SDTAP1, VALUE1, DLYSTEP1);
output [31:0] Q;
input D;
input PCLK, FCLKP, FCLKN, FCLKQP, FCLKQN;
input RESET;
output DF0, DF1;
input  SDTAP0, SDTAP1;
input  VALUE0,VALUE1;
input  [7:0] DLYSTEP0,DLYSTEP1;

parameter C_STATIC_DLY_0 = 0; //integer,0~255
parameter DYN_DLY_EN_0 = "FALSE";//"TRUE","FALSE"
parameter ADAPT_EN_0 = "FALSE";//"TRUE","FALSE"

parameter C_STATIC_DLY_1 = 0; //integer,0~255
parameter DYN_DLY_EN_1 = "FALSE";//"TRUE","FALSE"
parameter ADAPT_EN_1 = "FALSE";//"TRUE","FALSE"


wire D_a,D_b;
reg d_p,dq_p,dq_n,d_n,d_qp,dq_qp,dq_qn,d_qn;
reg db_p,dqb_p,dqb_n,db_n,db_qp,dqb_qp,dqb_qn,db_qn;
reg rstn_syn,cnt_0,cnt_1,d_up;
wire d_up_en;
reg dqn_reg0,dqnb_reg0,dn_reg0,dnb_reg0,dqp_reg0,dqpb_reg0,dp_reg0,dpb_reg0,dqn_reg1,dqnb_reg1,dn_reg1,dnb_reg1,dqp_reg1,dqpb_reg1,dp_reg1,dpb_reg1,dqn_reg2,dqnb_reg2,dn_reg2,dnb_reg2,dqp_reg2,dqpb_reg2,dp_reg2,dpb_reg2,dqn_reg3,dqnb_reg3,dn_reg3,dnb_reg3,dqp_reg3,dqpb_reg3,dp_reg3,dpb_reg3;
reg [31:0] D_data;
reg [31:0] Q_data;

wire grstn;
assign grstn = GSR.GSRO;


wire DF0,DF1;
IODELAY dly_0 (
    .DO(D_a), 
    .DF(DF0), 
    .DI(D), 
    .DLYSTEP(DLYSTEP0),
    .SDTAP(SDTAP0),
    .VALUE(VALUE0)
);
defparam dly_0.C_STATIC_DLY = C_STATIC_DLY_0;
defparam dly_0.DYN_DLY_EN = DYN_DLY_EN_0;
defparam dly_0.ADAPT_EN = ADAPT_EN_0;

IODELAY dly_1 (
    .DO(D_b), 
    .DF(DF1), 
    .DI(D), 
    .DLYSTEP(DLYSTEP1), 
    .SDTAP(SDTAP1), 
    .VALUE(VALUE1)
);
defparam dly_1.C_STATIC_DLY = C_STATIC_DLY_1;
defparam dly_1.DYN_DLY_EN = DYN_DLY_EN_1;
defparam dly_1.ADAPT_EN = ADAPT_EN_1;


always @(posedge FCLKP or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        d_p <= 1'b0;
        dq_p <= 1'b0;
        dq_n <= 1'b0;
    end else if (RESET) begin
        d_p <= 1'b0;
        dq_p <= 1'b0;
        dq_n <= 1'b0;
    end else begin
        d_p <= D_a;
        dq_p <= d_p;
        dq_n <= d_n;
    end
end

always @(posedge FCLKN or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        d_n <= 1'b0;
    end else if (RESET) begin
        d_n <= 1'b0;
    end else begin
        d_n <= D_a;
    end
end

always @(posedge FCLKQP or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        d_qp <= 1'b0;
        dq_qp <= 1'b0;
        dq_qn <= 1'b0;
    end else if (RESET) begin
        d_qp <= 1'b0;
        dq_qp <= 1'b0;
        dq_qn <= 1'b0;
    end else begin
        d_qp <= D_a;
        dq_qp <= d_qp;
        dq_qn <= d_qn;
    end
end

always @(posedge FCLKQN or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        d_qn <= 1'b0;
    end else if (RESET) begin
        d_qn <= 1'b0;
    end else begin
        d_qn <= D_a;
    end
end


always @(posedge FCLKP or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        db_p <= 1'b0;
        dqb_p <= 1'b0;
        dqb_n <= 1'b0;
    end else if (RESET) begin
        db_p <= 1'b0;
        dqb_p <= 1'b0;
        dqb_n <= 1'b0;
    end else begin
        db_p <= D_b;
        dqb_p <= db_p;
        dqb_n <= db_n;
    end
end

always @(posedge FCLKN or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        db_n <= 1'b0;
    end else if (RESET) begin
        db_n <= 1'b0;
    end else begin
        db_n <= D_b;
    end
end

always @(posedge FCLKQP or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        db_qp <= 1'b0;
        dqb_qp <= 1'b0;
        dqb_qn <= 1'b0;
    end else if (RESET) begin
        db_qp <= 1'b0;
        dqb_qp <= 1'b0;
        dqb_qn <= 1'b0;
    end else begin
        db_qp <= D_b;
        dqb_qp <= db_qp;
        dqb_qn <= db_qn;
    end
end

always @(posedge FCLKQN or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        db_qn <= 1'b0;
    end else if (RESET) begin
        db_qn <= 1'b0;
    end else begin
        db_qn <= D_b;
    end
end

always @(posedge FCLKP or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        dn_reg0 <= 1'b0;
        dp_reg0 <= 1'b0;
        dn_reg1 <= 1'b0;
        dp_reg1 <= 1'b0;
        dn_reg2 <= 1'b0;
        dp_reg2 <= 1'b0;
        dn_reg3 <= 1'b0;
        dp_reg3 <= 1'b0;
        dqn_reg0 <= 1'b0;
        dqp_reg0 <= 1'b0;
        dqn_reg1 <= 1'b0;
        dqp_reg1 <= 1'b0;
        dqn_reg2 <= 1'b0;
        dqp_reg2 <= 1'b0;
        dqn_reg3 <= 1'b0;
        dqp_reg3 <= 1'b0;
        dnb_reg0 <= 1'b0;
        dpb_reg0 <= 1'b0;
        dnb_reg1 <= 1'b0;
        dpb_reg1 <= 1'b0;
        dnb_reg2 <= 1'b0;
        dpb_reg2 <= 1'b0;
        dnb_reg3 <= 1'b0;
        dpb_reg3 <= 1'b0;
        dqnb_reg0 <= 1'b0;
        dqpb_reg0 <= 1'b0;
        dqnb_reg1 <= 1'b0;
        dqpb_reg1 <= 1'b0;
        dqnb_reg2 <= 1'b0;
        dqpb_reg2 <= 1'b0;
        dqnb_reg3 <= 1'b0;
        dqpb_reg3 <= 1'b0;
    end else if (RESET) begin
        dn_reg0 <= 1'b0;
        dp_reg0 <= 1'b0;
        dn_reg1 <= 1'b0;
        dp_reg1 <= 1'b0;
        dn_reg2 <= 1'b0;
        dp_reg2 <= 1'b0;
        dn_reg3 <= 1'b0;
        dp_reg3 <= 1'b0;
        dqn_reg0 <= 1'b0;
        dqp_reg0 <= 1'b0;
        dqn_reg1 <= 1'b0;
        dqp_reg1 <= 1'b0;
        dqn_reg2 <= 1'b0;
        dqp_reg2 <= 1'b0;
        dqn_reg3 <= 1'b0;
        dqp_reg3 <= 1'b0;
        dnb_reg0 <= 1'b0;
        dpb_reg0 <= 1'b0;
        dnb_reg1 <= 1'b0;
        dpb_reg1 <= 1'b0;
        dnb_reg2 <= 1'b0;
        dpb_reg2 <= 1'b0;
        dnb_reg3 <= 1'b0;
        dpb_reg3 <= 1'b0;
        dqnb_reg0 <= 1'b0;
        dqpb_reg0 <= 1'b0;
        dqnb_reg1 <= 1'b0;
        dqpb_reg1 <= 1'b0;
        dqnb_reg2 <= 1'b0;
        dqpb_reg2 <= 1'b0;
        dqnb_reg3 <= 1'b0;
        dqpb_reg3 <= 1'b0;
    end else begin
        dn_reg0 <= dq_n;
        dp_reg0 <= dq_p;
        dn_reg1 <= dn_reg0;
        dp_reg1 <= dp_reg0;
        dn_reg2 <= dn_reg1;
        dp_reg2 <= dp_reg1;
        dn_reg3 <= dn_reg2;
        dp_reg3 <= dp_reg2;
        dqn_reg0 <= dq_qn;
        dqp_reg0 <= dq_qp;
        dqn_reg1 <= dqn_reg0;
        dqp_reg1 <= dqp_reg0;
        dqn_reg2 <= dqn_reg1;
        dqp_reg2 <= dqp_reg1;
        dqn_reg3 <= dqn_reg2;
        dqp_reg3 <= dqp_reg2;

        dnb_reg0 <= dqb_n;
        dpb_reg0 <= dqb_p;
        dnb_reg1 <= dnb_reg0;
        dpb_reg1 <= dpb_reg0;
        dnb_reg2 <= dnb_reg1;
        dpb_reg2 <= dpb_reg1;
        dnb_reg3 <= dnb_reg2;
        dpb_reg3 <= dpb_reg2;
        dqnb_reg0 <= dqb_qn;
        dqpb_reg0 <= dqb_qp;
        dqnb_reg1 <= dqnb_reg0;
        dqpb_reg1 <= dqpb_reg0;
        dqnb_reg2 <= dqnb_reg1;
        dqpb_reg2 <= dqpb_reg1;
        dqnb_reg3 <= dqnb_reg2;
        dqpb_reg3 <= dqpb_reg2;
    end
end

always @(posedge FCLKQP or negedge grstn or posedge RESET) begin
    if (!grstn) begin    
        rstn_syn <= 1'b0;
    end else if(RESET) begin    
        rstn_syn <= 1'b0;
    end else begin
        rstn_syn <= 1'b1;
    end
end

always @(posedge FCLKQP or negedge grstn or negedge rstn_syn) begin
    if (!grstn) begin    
        cnt_0 <= 1'b0;
        cnt_1 <= 1'b0;
    end else if(!rstn_syn) begin    
        cnt_0 <= 1'b0;
        cnt_1 <= 1'b0;
    end else begin
        cnt_0 <= ~cnt_0;
        cnt_1 <= cnt_0 ^ cnt_1;
    end
end

assign d_up_en = cnt_0 && (~cnt_1);

always @(posedge FCLKQP or negedge grstn or negedge rstn_syn) begin
    if (!grstn) begin    
        d_up <= 1'b0;
    end else if(!rstn_syn) begin    
        d_up <= 1'b0;
    end else begin
        if(d_up_en) begin
            d_up <= 1'b1;
        end else begin
            d_up <= 1'b0;
        end
    end
end

always @(posedge FCLKQP or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        D_data <= 32'b0;
    end else if(RESET) begin
        D_data <= 32'b0;
    end else if(d_up) begin
        D_data[31] <= dqn_reg0;
        D_data[30] <= dqnb_reg0;
        D_data[29] <= dn_reg0;
        D_data[28] <= dnb_reg0;
        D_data[27] <= dqp_reg0;
        D_data[26] <= dqpb_reg0;
        D_data[25] <= dp_reg0;
        D_data[24] <= dpb_reg0;
        D_data[23] <= dqn_reg1;
        D_data[22] <= dqnb_reg1;
        D_data[21] <= dn_reg1;
        D_data[20] <= dnb_reg1;
        D_data[19] <= dqp_reg1;
        D_data[18] <= dqpb_reg1;
        D_data[17] <= dp_reg1;
        D_data[16] <= dpb_reg1;
        D_data[15] <= dqn_reg2;
        D_data[14] <= dqnb_reg2;
        D_data[13] <= dn_reg2;
        D_data[12] <= dnb_reg2;
        D_data[11] <= dqp_reg2;
        D_data[10] <= dqpb_reg2;
        D_data[9] <= dp_reg2;
        D_data[8] <= dpb_reg2;
        D_data[7] <= dqn_reg3;
        D_data[6] <= dqnb_reg3;
        D_data[5] <= dn_reg3;
        D_data[4] <= dnb_reg3;
        D_data[3] <= dqp_reg3;
        D_data[2] <= dqpb_reg3;
        D_data[1] <= dp_reg3;
        D_data[0] <= dpb_reg3;
    end
end

always @(posedge PCLK or negedge grstn or posedge RESET) begin
    if (!grstn) begin
        Q_data <= 32'b0;
    end else if (RESET) begin
        Q_data <= 32'b0;
    end else begin
        Q_data <= D_data;
    end
end

assign Q = Q_data;
specify
        (PCLK => Q[0]) = (0:0:0, 0:0:0);
        (PCLK => Q[1]) = (0:0:0, 0:0:0);
        (PCLK => Q[2]) = (0:0:0, 0:0:0);
        (PCLK => Q[3]) = (0:0:0, 0:0:0);
        (PCLK => Q[4]) = (0:0:0, 0:0:0);
        (PCLK => Q[5]) = (0:0:0, 0:0:0);
        (PCLK => Q[6]) = (0:0:0, 0:0:0);
        (PCLK => Q[7]) = (0:0:0, 0:0:0);
        (PCLK => Q[8]) = (0:0:0, 0:0:0);
        (PCLK => Q[9]) = (0:0:0, 0:0:0);
        (PCLK => Q[10]) = (0:0:0, 0:0:0);
        (PCLK => Q[11]) = (0:0:0, 0:0:0);
        (PCLK => Q[12]) = (0:0:0, 0:0:0);
        (PCLK => Q[13]) = (0:0:0, 0:0:0);
        (PCLK => Q[14]) = (0:0:0, 0:0:0);
        (PCLK => Q[15]) = (0:0:0, 0:0:0);
        (PCLK => Q[16]) = (0:0:0, 0:0:0);
        (PCLK => Q[17]) = (0:0:0, 0:0:0);
        (PCLK => Q[18]) = (0:0:0, 0:0:0);
        (PCLK => Q[19]) = (0:0:0, 0:0:0);
        (PCLK => Q[20]) = (0:0:0, 0:0:0);
        (PCLK => Q[21]) = (0:0:0, 0:0:0);
        (PCLK => Q[22]) = (0:0:0, 0:0:0);
        (PCLK => Q[23]) = (0:0:0, 0:0:0);
        (PCLK => Q[24]) = (0:0:0, 0:0:0);
        (PCLK => Q[25]) = (0:0:0, 0:0:0);
        (PCLK => Q[26]) = (0:0:0, 0:0:0);
        (PCLK => Q[27]) = (0:0:0, 0:0:0);
        (PCLK => Q[28]) = (0:0:0, 0:0:0);
        (PCLK => Q[29]) = (0:0:0, 0:0:0);
        (PCLK => Q[30]) = (0:0:0, 0:0:0);
        (PCLK => Q[31]) = (0:0:0, 0:0:0);
        (RESET => Q[0]) = (0:0:0, 0:0:0);
        (RESET => Q[1]) = (0:0:0, 0:0:0);
        (RESET => Q[2]) = (0:0:0, 0:0:0);
